  d.selected_v4=true;d.binding=binding;d.contract_file=pin(binding.at("contract"),{});const auto base=d.contract_file.parent_path();d.contract=eventio::read_json(d.contract_file);const auto&c=d.contract;
  require(c.at("schema")==binding.at("schema")&&c.at("all_physical_scalar_values_exact").get<bool>()&&c.at("all_old_four_auxiliary_values_exact").get<bool>()&&c.at("all_old_source_ID_UV_Query_W_and_finite_paths_exact").get<bool>()&&c.at("old_cell_anchor_KKT_and_graph_bounds_preserved").get<bool>()&&c.at("only_new_rows_may_be_profiled").get<bool>()&&!c.at("old_graph_or_AL_checkpoint_resumed").get<bool>(),"wrong source-append contract semantics");
  pin(c.at("consumer"),base);const auto canonicalFile=pin(c.at("canonical_source_packet"),base),oldFile=pin(c.at("old_source_packet"),base);const auto canonical=eventio::read_json(canonicalFile),old=eventio::read_json(oldFile);pin(c.at("canonical_source_guard"),base);
  const auto&s=c.at("selected_complete_capture_v4");for(const char*k:{"model","checkpoint","capture_state_binding","explicit_nuisance_manifest","actual_RS_status"})pin(s.at(k),base);
  std::ifstream in(pin(s.at("checkpoint"),base));const auto cp=read_checkpoint(in);
  require(cp.state.token()==s.at("state_token")&&binding.at("state_token")==s.at("state_token")&&cp.state.data().identity.objective_id=="rinkfit.sourceUV_trueRS_finite_capture.v4"&&s.at("objective_id")=="rinkfit.sourceUV_trueRS_finite_capture.v4"&&binding.at("objective_id")==s.at("objective_id"),"selected complete token or mode mismatch");
  require(cp.state.data().identity.source_id==c.at("old_source_packet").at("sha256"),"parent checkpoint has another source");
  const auto sb=eventio::read_json(pin(s.at("capture_state_binding"),base));require(sb.at("state_token")==cp.state.token()&&sb.at("model_sha256")==s.at("model").at("sha256")&&sb.at("packet_sha256")==c.at("old_source_packet").at("sha256")&&!sb.at("formal_Query_closed").get<bool>(),"selected saved source state mismatch");
  const auto selection=eventio::read_json(pin(c.at("root_selection"),base));require(selection.at("selected_for_next_source_batch").get<bool>()&&selection.at("state_token")==cp.state.token()&&!selection.at("quality_accepted").get<bool>()&&selection.at("checkpoint")==s.at("checkpoint")&&selection.at("model")==s.at("model"),"different explicitly selected numerical parent");
  const auto nd=eventio::read_json(pin(selection.at("native_domain_receipt"),base));require(nd.at("state_token")==cp.state.token()&&nd.at("g_max_positive").get<double>()==0.&&nd.at("h_max_abs").get<double>()==0.,"selected same-token native numerical domain fails");pin(selection.at("independent_audit"),base);pin(selection.at("configuration"),base);
